import React, { useState } from "react";

export default function Registration({ onRegistered }) {
  const [form, setForm] = useState({
    name: "",
    dob: "",
    country: "",
    phone: "",
    idProof: "",
    city: "",
  });
  const [registered, setRegistered] = useState(false);
  const [blockId, setBlockId] = useState("");

  const cities = ["Varanasi", "Jaipur", "Delhi", "Mumbai", "Goa"];

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const generateBlockId = () => {
    return "KR-" + Math.floor(10000 + Math.random() * 90000);
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const { name, dob, country, phone, idProof, city } = form;
    if (!name || !dob || !country || !phone || !idProof || !city) {
      alert("Please fill all fields");
      return;
    }
    const id = generateBlockId();
    setBlockId(id);
    setRegistered(true);
    // send back to App
    if (onRegistered) onRegistered({ ...form, blockId: id });
  };

  return (
    <div style={root}>
      <style>{`
        @keyframes cardIn { from { transform: translateY(18px); opacity: 0 } to { transform: translateY(0); opacity: 1 } }
      `}</style>

      {!registered ? (
        <div style={card}>
          <h1 style={title}>🙏 Namaste Tourist</h1>
          <p style={subtitle}>Tell us about yourself — so we can make your journey safe & soulful.</p>

          <form onSubmit={handleSubmit} style={formStyle}>
            <input name="name" value={form.name} onChange={handleChange} placeholder="Full Name" style={input} />
            <input name="dob" value={form.dob} onChange={handleChange} type="date" style={input} />
            <input name="country" value={form.country} onChange={handleChange} placeholder="Country of Origin" style={input} />
            <input name="phone" value={form.phone} onChange={handleChange} placeholder="Phone Number" style={input} />
            <input name="idProof" value={form.idProof} onChange={handleChange} placeholder="Aadhaar / Passport / ID Proof" style={input} />
            <select name="city" value={form.city} onChange={handleChange} style={input}>
              <option value="">-- Select City to Visit --</option>
              {cities.map((c) => (<option key={c} value={c}>{c}</option>))}
            </select>

            <button type="submit" style={primaryBtn}>Generate Block ID</button>
          </form>
        </div>
      ) : (
        <div style={{...card, alignItems: "center"}}>
          <h2 style={{margin:0}}>🎉 Registration Successful</h2>
          <p style={{color:"#5b3a1a"}}>Welcome, <strong>{form.name}</strong></p>
          <div style={{margin:"14px 0", padding:"10px 16px", borderRadius:10, background:"#fff7ed", border:"1px solid #ffecd1"}}>
            <strong>Block ID:</strong> <span style={{color:"#d35400", marginLeft:8}}>{blockId}</span>
          </div>
          <p style={{fontSize:13, color:"#6b4d2b"}}>You chose to visit <strong>{form.city}</strong>. Proceed to plan your journey.</p>
          <button onClick={() => onRegistered({ ...form, blockId })} style={primaryBtn}>Proceed to Journey →</button>
        </div>
      )}
    </div>
  );
}

/* styles */
const root = {
  minHeight: "100vh",
  display: "flex",
  justifyContent: "center",
  alignItems: "center",
  background: "linear-gradient(135deg, #FFF2E6 0%, #FFE0B3 50%, #FFD1A6 100%)",
  fontFamily: "'Poppins', sans-serif",
  padding: 20,
};

const card = {
  background: "rgba(255,255,255,0.95)",
  width: 420,
  maxWidth: "95%",
  padding: 28,
  borderRadius: 16,
  boxShadow: "0 12px 35px rgba(0,0,0,0.12)",
  display: "flex",
  flexDirection: "column",
  gap: 10,
  animation: "cardIn 450ms ease both",
};

const title = { color: "#a24b00", margin: 0, fontSize: 28, textAlign: "center" };
const subtitle = { color: "#6b4d2b", fontSize: 14, marginTop: 6, textAlign: "center" };

const formStyle = { display: "flex", flexDirection: "column", gap: 10, marginTop: 8 };
const input = {
  padding: "10px 12px",
  borderRadius: 10,
  border: "1px solid #e9e1d6",
  outline: "none",
  fontSize: 14,
  textAlign: "center"
};

const primaryBtn = {
  marginTop: 6,
  padding: "12px 14px",
  background: "linear-gradient(90deg,#ff8b2d,#ff6f00)",
  color: "white",
  border: "none",
  borderRadius: 10,
  cursor: "pointer",
  fontWeight: 700,
  fontSize: 15
};
